CREATE TABLE "users" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "email" varchar(255) UNIQUE NOT NULL,
  "password_hash" varchar(100) NOT NULL,
  "role" varchar(10) NOT NULL DEFAULT 'USER',
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_users_role" CHECK (role IN ('USER', 'ADMIN'))
);

CREATE TABLE "genres" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL
);

CREATE TABLE "movies" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "title" varchar(200) NOT NULL,
  "description" text,
  "poster_url" varchar(500),
  "duration_min" integer NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  CONSTRAINT "chk_movies_duration" CHECK (duration_min > 0)
);

CREATE TABLE "movie_genres" (
  "movie_id" bigint NOT NULL,
  "genre_id" bigint NOT NULL,
  PRIMARY KEY ("movie_id", "genre_id")
);

CREATE TABLE "halls" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "name" varchar(50) UNIQUE NOT NULL,
  "rows" integer NOT NULL,
  "seats_per_row" integer NOT NULL,
  CONSTRAINT "chk_halls_size" CHECK (rows > 0 AND seats_per_row > 0)
);

CREATE TABLE "seats" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "hall_id" bigint NOT NULL,
  "row_label" varchar(2) NOT NULL,
  "number" integer NOT NULL
);

CREATE TABLE "showtimes" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "movie_id" bigint NOT NULL,
  "hall_id" bigint NOT NULL,
  "starts_at" timestamptz NOT NULL,
  "ends_at" timestamptz NOT NULL,
  "base_price" numeric(10,2) NOT NULL,
  CONSTRAINT "chk_showtimes_times" CHECK (ends_at > starts_at),
  CONSTRAINT "chk_showtimes_price" CHECK (base_price >= 0)
);

CREATE TABLE "reservations" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" bigint NOT NULL,
  "showtime_id" bigint NOT NULL,
  "status" varchar(10) NOT NULL DEFAULT 'ACTIVE',
  "total_price" numeric(10,2) NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT (now()),
  "cancelled_at" timestamptz,
  CONSTRAINT "chk_reservations_status" CHECK (status IN ('ACTIVE', 'CANCELLED'))
);

CREATE TABLE "reservation_seats" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "reservation_id" bigint NOT NULL,
  "showtime_id" bigint NOT NULL,
  "seat_id" bigint NOT NULL,
  "price" numeric(10,2) NOT NULL,
  "active" boolean NOT NULL DEFAULT true
);

CREATE UNIQUE INDEX ON "seats" ("hall_id", "row_label", "number");

CREATE INDEX ON "showtimes" ("starts_at");

CREATE INDEX ON "showtimes" ("movie_id");

CREATE INDEX ON "reservations" ("user_id");

CREATE INDEX ON "reservations" ("showtime_id");

CREATE INDEX ON "reservation_seats" ("reservation_id");

CREATE INDEX ON "reservation_seats" ("showtime_id");

COMMENT ON COLUMN "seats"."row_label" IS 'A, B, C ...';

COMMENT ON TABLE "showtimes" IS 'No overlap in one hall: EXCLUDE constraint, added in SQL (DBML cannot express it)';

COMMENT ON COLUMN "showtimes"."ends_at" IS 'starts_at + duration + cleaning buffer, set by the service';

COMMENT ON TABLE "reservation_seats" IS 'No double booking: partial UNIQUE (showtime_id, seat_id) WHERE active, added in SQL';

COMMENT ON COLUMN "reservation_seats"."showtime_id" IS 'copied from reservation so the partial unique index can use it';

ALTER TABLE "movie_genres" ADD FOREIGN KEY ("movie_id") REFERENCES "movies" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "movie_genres" ADD FOREIGN KEY ("genre_id") REFERENCES "genres" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "seats" ADD FOREIGN KEY ("hall_id") REFERENCES "halls" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "showtimes" ADD FOREIGN KEY ("movie_id") REFERENCES "movies" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "showtimes" ADD FOREIGN KEY ("hall_id") REFERENCES "halls" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservations" ADD FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservations" ADD FOREIGN KEY ("showtime_id") REFERENCES "showtimes" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservation_seats" ADD FOREIGN KEY ("reservation_id") REFERENCES "reservations" ("id") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservation_seats" ADD FOREIGN KEY ("showtime_id") REFERENCES "showtimes" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reservation_seats" ADD FOREIGN KEY ("seat_id") REFERENCES "seats" ("id") ON DELETE RESTRICT DEFERRABLE INITIALLY IMMEDIATE;

CREATE UNIQUE INDEX ux_seat_once_per_showtime
    ON reservation_seats (showtime_id, seat_id)
    WHERE active;

CREATE EXTENSION IF NOT EXISTS btree_gist;

ALTER TABLE showtimes ADD CONSTRAINT no_overlap_in_hall
    EXCLUDE USING gist (
    hall_id WITH =,
    tstzrange(starts_at, ends_at) WITH &&
  );
